import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

import { TRANSLATIONS } from '../nav-language.js';

const read = (name) => readFileSync(new URL(`../${name}`, import.meta.url), 'utf8');

function parseCss(rawText, baseOff = 0) {
  const text = rawText.replace(/\/\*[\s\S]*?\*\//g, (m) => m.replace(/[^\n]/g, ' '));
  const rules = [];
  const n = text.length;
  let i = 0;
  const stack = [];
  while (i < n) {
    const j = text.indexOf('{', i);
    const k = text.indexOf('}', i);
    if (j === -1 && k === -1) break;
    if (k !== -1 && (j === -1 || k < j)) {
      if (stack.length) stack.pop();
      i = k + 1;
      continue;
    }
    const sel = text.slice(i, j).trim();
    const line = text.slice(0, i).split('\n').length;
    let depth = 1;
    let p = j + 1;
    while (p < n && depth > 0) {
      if (text[p] === '{') depth += 1;
      else if (text[p] === '}') depth -= 1;
      p += 1;
    }
    const body = text.slice(j + 1, p - 1);
    if (sel.startsWith('@media') || sel.startsWith('@supports')) {
      stack.push(sel);
      for (const r of parseCss(body, baseOff + j + 1)) {
        rules.push({ ...r, line: line + r.line - 1, media: [...stack, ...r.media].join(' | ') });
      }
      stack.pop();
    } else if (!sel.startsWith('@')) {
      rules.push({ selector: sel, body, line, media: stack.join(' | ') });
    }
    i = p;
  }
  return rules;
}

function fontSizes(body) {
  const out = [];
  for (const m of body.matchAll(/font-size\s*:\s*([\d.]+)(px|rem)/g)) {
    out.push({ value: parseFloat(m[1]), unit: m[2] });
  }
  for (const m of body.matchAll(/font\s*:\s*[^;{}]*?\b([\d.]+)(px|rem)\b/g)) {
    out.push({ value: parseFloat(m[1]), unit: m[2] });
  }
  return out;
}

const cssCache = {};
function cssRules(file) {
  if (!cssCache[file]) cssCache[file] = parseCss(read(file));
  return cssCache[file];
}

const normM = (m) => (m || '').replace(/\s+/g, '');
function mediaApplies(ruleMedia, rowMedia) {
  const rm = normM(ruleMedia);
  const qm = normM(rowMedia);
  if (!rm) return true;
  if (!qm) return false;
  if (rm === qm) return true;
  if (qm.includes('620') && rm.includes('700')) return true;
  return false;
}

function effectiveSize(file, selector, rowMedia) {
  const all = cssRules(file).filter((r) => mediaApplies(r.media, rowMedia || ''));
  let best = null;
  for (const r of all) {
    if (r.selector.includes(':where(')) continue;
    const comps = r.selector.split(',').map((c) => c.trim());
    if (!comps.includes(selector) && r.selector !== selector) continue;
    const sz = fontSizes(r.body);
    if (sz.length) best = { ...sz[sz.length - 1], line: r.line };
  }
  return best;
}

