for (const row of DATA) {
  const name = `${row.disp} ${row.file}:${row.line} ${row.selector} (${row.size}${row.size < 1 ? 'rem' : 'px'}${row.media ? ' ' + row.media : ''})`;
  test(name, () => {
    if (row.file.endsWith('.js')) {
      const lines = read(row.file).split('\n');
      const ln = lines[row.line - 1] || '';
      const m = ln.match(/font-size\s*:\s*([\d.]+)px/);
      assert.ok(m, `no font-size on line ${row.line} (line moved?)`);
      assert.ok(parseFloat(m[1]) >= 11, `inline font-size is ${m[1]}px, floor is 11px`);
      return;
    }
    if (row.disp === 'DEAD') {
      const allRules = cssRules(row.file).filter((r) => mediaApplies(r.media, row.media || ''));
      const later = allRules.filter((r) => r.line > row.line);
      const shadow = later.filter((r) => {
        const comps = r.selector.split(',').map((c) => c.trim());
        return (comps.includes(row.selector) || r.selector === row.selector) && fontSizes(r.body).length > 0;
      });
      assert.ok(shadow.length > 0, 'no later rule sets a font-size for this selector — the declaration is not dead');
      return;
    }
    if (row.disp === 'STAY') {
      const eff = effectiveSize(row.file, row.selector, row.media || '');
      assert.ok(eff, 'no rule sets a size for this selector');
      if (eff.unit === 'px') assert.equal(eff.value, row.size, `effective size moved from ${row.size}px`);
      else assert.ok(Math.abs(eff.value - row.size) < 1e-9, `effective size moved from ${row.size}rem`);
      return;
    }
    const floor = row.disp === 'RAISE10' ? 10 : 11;
    const eff = effectiveSize(row.file, row.selector, row.media || '');
    assert.ok(eff, 'no rule sets a size for this selector');
    const px = eff.unit === 'px' ? eff.value : eff.value * 16;
    assert.ok(px >= floor, `effective size is ${eff.value}${eff.unit} (line ${eff.line}), floor is ${floor}px`);
  });
}

test('sweep: no content text below 11px anywhere in the 5 CSS files or the 28 JS files', () => {
  const cssFiles = ['styles.css', 'nav.css', 'components.css', 'dashboard.css', 'screen-router.css'];
  const stay = new Set();
  for (const r of DATA.filter((x) => x.disp === 'STAY')) {
    for (const c of r.selector.split(',').map((x) => x.trim())) {
      stay.add(`${r.file}|${c}|${normM(r.media || '')}`);
    }
  }
  const raise10 = new Set(DATA.filter((r) => r.disp === 'RAISE10').map((r) => `${r.file}|${r.selector}`));
  // DS-0 exception: .bottom-nav-badge stays 10px by design (see header).
  const ds0Exceptions = new Set(['nav.css|.bottom-nav-badge']);
  for (const f of cssFiles) {
    const rules = cssRules(f);
    const cands = new Map();
    for (const r of rules) {
      for (const s of fontSizes(r.body)) {
        const px = s.unit === 'px' ? s.value : s.value * 16;
        if (px < 11) {
          for (const c of r.selector.split(',').map((x) => x.trim())) {
            if (!cands.has(c)) cands.set(c, new Set());
            cands.get(c).add(r.media);
          }
        }
      }
    }
    for (const [sel, medias] of cands) {
      for (const med of [...medias, '']) {
        if (med.includes('print')) continue;
        const eff = effectiveSize(f, sel, med);
        if (!eff) continue;
        const px = eff.unit === 'px' ? eff.value : eff.value * 16;
        if (px < 11) {
          const ok = stay.has(`${f}|${sel}|${normM(med)}`) ||
            (raise10.has(`${f}|${sel}`) && eff.value === 10 && eff.unit === 'px') ||
            (ds0Exceptions.has(`${f}|${sel}`) && eff.value === 10 && eff.unit === 'px');
          assert.ok(ok, `${f} ${sel} @${med || '(base)'} renders ${eff.value}${eff.unit} — a content site the table missed`);
        }
      }
    }
  }
  const jsFiles = [...new Set(DATA.filter((r) => r.file.endsWith('.js')).map((r) => r.file))];
  const printy = /print|slip|certificate|voucher|letterhead|manifest|report/i;
  for (const f of jsFiles) {
    const lines = read(f).split('\n');
    const fns = [];
    lines.forEach((ln, i) => {
      const m = ln.match(/^(?:export\s+)?(?:async\s+)?function\s+([A-Za-z0-9_$]+)\s*\(/) ||
                ln.match(/^export\s+const\s+([A-Za-z0-9_$]+)\s*=\s*(?:async\s*)?\(/);
      if (m) fns.push({ name: m[1], line: i + 1 });
    });
    lines.forEach((ln, i) => {
      const m = ln.match(/font-size\s*:\s*([\d.]+)px/);
      if (!m || parseFloat(m[1]) >= 11) return;
      let fn = null;
      for (const x of fns) {
        if (x.line <= i + 1) fn = x;
        else break;
      }
      assert.ok(fn && printy.test(fn.name),
        `${f}:${i + 1} (${m[1]}px) is on-screen text below the floor, in ${fn ? fn.name : '(no function)'}`);
    });
  }
});

test('C-guard: styles.css @media print block is untouched (still has 8px)', () => {
  const styles = read('styles.css');
  assert.ok(/@media print[\s\S]*?font-size:\s*8px/.test(styles), 'print block changed — print is out of scope for 97');
});

test('C-guard: QA modules are untouched (sample still 10px)', () => {
  const qa = read('qa-tube-slitting-access.js');
  assert.ok(/font-size:\s*10px/.test(qa), 'QA file changed — QA is out of scope for 97');
});

test('DS-0 exception: .bottom-nav-badge stays 10px on an 18px line', () => {
  // Deliberate DS-0 design pin (ds0-design-system.test.js: 'badge text must
  // be 10px on an 18px line'): the badge is an 18px pill docked to a 22px
  // icon. The 97 floor yields to it — see the file header. Do NOT "fix" this
  // to 11px without a parent decision overriding DS-0.
  const nav = read('nav.css');
  const m = nav.match(/\.bottom-nav-badge\s*\{([^}]*)\}/);
  assert.ok(m, '.bottom-nav-badge rule missing from nav.css');
  assert.ok(m[1].includes('font: 800 10px/18px'), 'badge text must stay 10px on an 18px line (DS-0)');
  assert.ok(m[1].includes('height: 18px') && m[1].includes('min-width: 18px'), 'badge must stay an 18px pill');
});

test('C-guard: the dead .command-palette-trigger rule set is absent (Sharafat 96 A3, kept absent)', () => {
  assert.ok(!read('nav.css').includes('.command-palette-trigger'), 'trigger rule set is back in nav.css');
  assert.ok(!read('dark-contrast.css').includes('.command-palette-trigger'), 'trigger rule set is back in dark-contrast.css');
});
